<?php
namespace App\Services\Commerce;use App\Models\{Order,Payment,Ticket};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;class PaymentFinalizer{public function finalizePaystack(string$r,array$d):Order{return DB::transaction(function()use($r,$d){$p=Payment::where('reference',$r)->lockForUpdate()->firstOrFail();$o=Order::whereKey($p->order_id)->lockForUpdate()->firstOrFail();if($p->status===Payment::STATUS_SUCCESS&&$o->isPaid())return$o->load('items.tickets');if(($d['status']??'')!=='success'){if(in_array($d['status']??'',['failed','abandoned','reversed'],true))$p->update(['status'=>'failed']);return$o;}if(($d['reference']??null)!==$p->reference||(int)($d['amount']??-1)!==(int)$p->amount_minor||strtoupper($d['currency']??'')!==strtoupper($p->currency)){$p->update(['status'=>'review','verified_at'=>now()]);$o->update(['status'=>'payment_review']);return$o->fresh()->load('items.tickets');}$p->update(['status'=>'success','provider_transaction_id'=>(string)($d['id']??''),'paid_at'=>$d['paid_at']??now(),'verified_at'=>now()]);$o->update(['status'=>'paid','paid_at'=>$d['paid_at']??now()]);foreach($o->items()->with('tickets')->get()as$i)for($n=$i->tickets->count();$n<$i->quantity;$n++){$raw=Str::random(48);Ticket::create(['public_id'=>(string)Str::ulid(),'order_item_id'=>$i->id,'event_id'=>$i->event_id,'ticket_type_id'=>$i->ticket_type_id,'token'=>$raw,'token_hash'=>hash('sha256',$raw),'admit_count'=>max(1,$i->people_per_unit),'status'=>'valid','issued_at'=>now()]);}return$o->fresh()->load('items.tickets','payments','allocations');},3);}}